using Microsoft.AspNetCore.Authorization;
using Microsoft.Extensions.DependencyInjection;
using System.Security.Claims;
var services = new ServiceCollection();
services.AddLogging();
services.AddAuthorization(options => options.AddPolicy("Manage", p => p.RequireRole("Admin")));
using var provider = services.BuildServiceProvider();
var authorization = provider.GetRequiredService<IAuthorizationService>();
string role = "Admin";
var user = new ClaimsPrincipal(new ClaimsIdentity(new[] { new Claim(ClaimTypes.Role, role) }, "Fixture"));
Console.WriteLine((await authorization.AuthorizeAsync(user, null, "Manage")).Succeeded);

